package main

import (
	"log"
	"net/http"
	"net/http/pprof"
)

func serveDebug() {
	mux := http.NewServeMux()
	mux.HandleFunc("/debug/pprof/", pprof.Index)
	mux.HandleFunc("/debug/pprof/profile", pprof.Profile)
	http.ListenAndServe(":6060", mux)
}

func main() {
	go serveDebug()
	log.Fatal(http.ListenAndServe("127.0.0.1:8080", http.NotFoundHandler()))
}
